package com.example.rokidkeyboardbridge;
public final class QuickSpeechChecks {
 static int n;static void ok(boolean v){n++;if(!v)throw new AssertionError("quick speech "+n);}interface Work{void run();}static void rejects(Work work){boolean failed=false;try{work.run();}catch(IllegalArgumentException e){failed=true;}ok(failed);}
 public static int run(){n=0;SpeechQuickKey key=new SpeechQuickKey();ok(key.event(23,0,0,false,100)==0);ok(key.event(4,0,0,true,100)==0);ok(key.event(66,0,0,true,100)==0);ok(key.event(23,0,0,true,100)==1);ok(key.event(23,0,1,true,120)==2);ok(key.event(23,1,0,false,130)==2);ok(key.event(23,1,0,false,140)==0);ok(key.event(109,0,0,true,200)==2);ok(key.event(109,1,0,true,210)==2);ok(key.event(23,0,0,true,600)==1);ok(key.event(23,1,0,true,620)==2);ok(key.event(109,0,0,true,1100)==1);key.clear();ok(key.event(109,1,0,true,1110)==0);ok(key.event(23,0,1,true,2000)==2);ok(key.event(23,1,0,true,2100)==2);ok(key.event(23,0,0,false,3000)==0);
 ConversationPlaybackState s=new ConversationPlaybackState();ok(!s.pausable(1));ok(!s.resumable(1));s.begin("answer-a",new String[]{"first.","second.","third."},1);ok(s.pausable(1));ok(!s.resumable(1));s.mark(1,1);s.pause("answer-a",1,2);ok(!s.pausable(2));ok(s.resumable(2));ok(s.current(2).equals("answer-a"));ok(s.text("answer-a",2,false).equals("second.\nthird."));s.mark(1,2);s.finish(1);ok(s.resumable(2));ok(s.text("answer-a",2,false).startsWith("second."));String resume=s.text("answer-a",2,false);s.begin("answer-a",resume.split("\n"),3);ok(s.pausable(3));ok(!s.resumable(3));s.mark(2,1);s.pause("answer-a",3,4);ok(s.text("answer-a",4,false).equals(resume));s.begin("answer-b",new String[]{"new answer"},5);rejects(()->s.text("answer-a",5,false));ok(s.current(4).isEmpty());ok(!s.resumable(4));s.finish(5);ok(!s.pausable(5));ok(!s.resumable(5));ok(s.text("answer-b",5,true).equals("new answer"));rejects(()->s.pause("answer-b",5,6));s.begin("empty",new String[0],6);ok(!s.pausable(6));ok(!s.resumable(6));return n;}
}
